var getLongestSubsequence = function(words, groups) {
    const ans = [];
    let last = -1;
    for (let i = 0; i < words.length; i++) {
        if (groups[i] !== last) {
            ans.push(words[i]);
            last = groups[i];
        }
    }
    return ans;
};
